function ConnectionMultiSelect({ connections, selectedIds, onChange, includeRoster = false }: { connections: TeacherConnection[]; selectedIds: string[]; onChange: (ids: string[]) => void; includeRoster?: boolean }) {
  const { t } = useAppPreferences();
  const [search, setSearch] = useState(''); const [open, setOpen] = useState(false);
  const query = normalizeFacet(search);
  const matching = connections.filter((connection) => !query || normalizeFacet([connection.student_name, connection.student_email, ...connection.subjects.map((scope) => scope.subject_label || scope.subject_key)].join(' ')).includes(query));
  const names = connections.filter((connection) => selectedIds.includes(String(connection.id))).map((connection) => connection.student_name);
  return <View style={styles.connectionPicker}>
    <Text style={styles.actionLabel}>{t('resources.studentSelector')}</Text>
    <Field accessibilityLabel={t('resources.searchConnectedStudents')} value={search} onChangeText={(value) => { setSearch(value); setOpen(true); }} placeholder={t('resources.searchConnectedStudents')} />
    <Pressable accessibilityRole="button" accessibilityState={{ expanded: open }} onPress={() => setOpen((value) => !value)} style={[styles.connectionSelect, open && styles.connectionSelectOpen]}><Text numberOfLines={1} style={styles.connectionSelectText}>{selectedIds.length ? t('resources.selectedStudents', { count: selectedIds.length }) : t(includeRoster ? 'resources.chooseProgramStudents' : 'resources.chooseConnectedStudents')}</Text><Text style={styles.connectionSelectArrow}>{open ? '▴' : '▾'}</Text></Pressable>
    {names.length ? <Text numberOfLines={2} style={styles.connectionSelectedNames}>{names.join(' · ')}</Text> : null}
    {open ? <ScrollView nestedScrollEnabled style={styles.connectionMenu} contentContainerStyle={styles.connectionMenuContent}>{matching.length ? matching.map((connection) => { const id = String(connection.id); const checked = selectedIds.includes(id); return <Pressable key={id} accessibilityRole="checkbox" accessibilityState={{ checked }} onPress={() => onChange(checked ? selectedIds.filter((item) => item !== id) : [...selectedIds, id])} style={[styles.connectionOption, checked && styles.connectionOptionActive]}><View style={[styles.connectionCheck, checked && styles.connectionCheckActive]}><Text style={styles.connectionCheckText}>{checked ? '✓' : ''}</Text></View><View style={styles.connectionOptionCopy}><Text style={styles.connectionOptionName}>{connection.student_name}</Text><Text numberOfLines={1} style={styles.connectionOptionDetail}>{connection.roster_student_id ? t('resources.localStudent') : connection.student_email || connection.subjects.map((scope) => canonicalSubjectLabel(scope.subject_label || scope.subject_key, t)).join(' · ')}</Text></View></Pressable>; }) : <Text style={styles.connectionEmpty}>{t(includeRoster ? 'resources.noProgramStudents' : 'resources.noConnectedStudents')}</Text>}</ScrollView> : null}
  </View>;
}
function labelize(key: string) { return key.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase()); }
function resourceLabel(value: string, t: (key: string) => string) { const code = value.trim().toLowerCase().replace(/[ -]+/g, '_'); for (const key of [`resources.term.${code}`, `student.exercise.${code}`]) { const translated = t(key); if (translated !== key) return translated; } return /^[a-z][a-z0-9_]+$/i.test(value) ? labelize(value) : value; }
function resourceValue(value: unknown, t: (key: string) => string) { if (typeof value === 'boolean') return t(value ? 'resources.yes' : 'resources.no'); if (typeof value !== 'string') return primitive(value); const code = value.trim(); if (!/^[a-z][a-z0-9_]*$/i.test(code)) return value; for (const key of [`resources.term.${code.toLowerCase()}`, `student.exercise.${code.toLowerCase()}`]) { const translated = t(key); if (translated !== key) return translated; } return code.includes('_') ? labelize(code) : value; }
function normalizeFacet(value: unknown) { return String(value ?? '').trim().toLocaleLowerCase().replace(/[_-]+/g, ' ').replace(/\s+/g, ' '); }
function primitive(value: unknown) { if (typeof value === 'boolean') return value ? 'Yes' : 'No'; if (value === null || value === undefined) return ''; return String(value); }
function today() { return new Date().toISOString().slice(0, 10); }
function youtubeId(value: string) { return value.match(/(?:youtu\.be\/|youtube(?:-nocookie)?\.com\/(?:watch\?v=|embed\/|shorts\/))([A-Za-z0-9_-]{6,})/i)?.[1] || ''; }

function ContentValue({ name, value, depth = 0 }: { name: string; value: unknown; depth?: number }) {
  const { t } = useAppPreferences();
  const normalizedName = name.toLowerCase();
  if (OMIT_KEYS.has(name) || normalizedName.includes('base64') || normalizedName.includes('image') || normalizedName.includes('thumbnail')) return null;
  if (value === null || value === '' || value === undefined || (Array.isArray(value) && value.length === 0)) return null;
  if (depth > 3) return null;
  if (Array.isArray(value)) return <Disclosure title={resourceLabel(name, t)} summary={t('resources.itemCount', { count: value.length })} defaultOpen={depth === 0 && value.length <= 4} style={styles.contentSection}>{value.map((item, index) => typeof item === 'object' && item !== null ? <Panel key={index} style={styles.nestedCard}>{Object.entries(item as Record<string, unknown>).map(([key, child]) => <ContentValue key={key} name={key} value={child} depth={depth + 1} />)}</Panel> : <Text key={index} style={styles.bullet}>• {resourceValue(item, t)}</Text>)}</Disclosure>;
  if (typeof value === 'object') { const entries = Object.entries(value as Record<string, unknown>); return <Disclosure title={resourceLabel(name, t)} summary={t('resources.fieldCount', { count: entries.length })} defaultOpen={depth === 0 && entries.length <= 5} style={styles.contentSection}>{entries.map(([key, child]) => <ContentValue key={key} name={key} value={child} depth={depth + 1} />)}</Disclosure>; }
  const display = resourceValue(value, t);
  if (display.startsWith('data:') || display.length > 12000) return null;
  return <View style={styles.contentLine}><Text style={styles.contentLabel}>{resourceLabel(name, t)}</Text><Text style={styles.contentText}>{display}</Text></View>;
}

function GridPreview({ grid, watermark }: { grid: string[][]; watermark?: string }) {
  const columns = Math.max(1, grid[0]?.length || 1);
  const cell = Math.min(32, 320 / columns);
  return <View style={[styles.gridFrame, { width: columns * cell }]}>
    {watermark ? <Image source={{ uri: watermark }} style={styles.gridWatermark} contentFit="contain" /> : null}
    {grid.map((row, rowIndex) => <View key={rowIndex} style={styles.gridRow}>{row.map((letter, columnIndex) => <Text key={columnIndex} style={[styles.gridCell, { width: cell, height: cell, lineHeight: cell - 2 }]}>{letter}</Text>)}</View>)}
  </View>;
}

function ResourceDetailContent({ kind, detail, locale, variant }: { kind: PublicResourceKind; detail: Record<string, unknown>; locale: 'en' | 'es' | 'tr'; variant: 'full' | 'student' | 'teacher' | 'answers' }) {
  const { t } = useAppPreferences();
  if (kind === 'plan' || kind === 'worksheet' || kind === 'exam') {
    const sections = resourceSections(detail, kind === 'plan' ? 'full' : variant, locale);
    return <View style={styles.structuredContent}>{sections.map((section, index) => <View key={`${section.heading}-${index}`} style={styles.documentSection}>{section.heading ? <Text style={styles.structuredTitle}>{resourceLabel(section.heading, t)}</Text> : null}{section.visuals?.map((url, visualIndex) => <Image key={visualIndex} source={{ uri: url }} style={styles.documentVisual} contentFit="contain" />)}{(kind === 'worksheet' && (section.table || section.grid) ? [] : section.lines).map((line, lineIndex) => <Text key={lineIndex} style={styles.contentText}>{resourceValue(line, t)}</Text>)}{section.table?.map((cells, rowIndex) => <View key={rowIndex} style={styles.documentRow}>{cells.map((cell, cellIndex) => <Text key={cellIndex} style={[styles.contentText, { flex: cellIndex === 1 && cells.length === 3 ? 0.3 : 1 }]}>{resourceValue(cell, t)}</Text>)}</View>)}{section.grid ? <GridPreview grid={section.grid} watermark={section.watermark} /> : null}</View>)}</View>;
  }
  if (kind === 'program') {
    const units = Array.isArray(detail.units) ? detail.units as Record<string, unknown>[] : [];
    const topics = Array.isArray(detail.topics) ? detail.topics as Record<string, unknown>[] : [];
    return <View style={styles.structuredContent}>
      {detail.program_overview ? <View style={styles.overviewPanel}><Text style={styles.structuredTitle}>{t('resources.programOverview')}</Text><Text style={styles.overviewText}>{resourceValue(detail.program_overview, t)}</Text></View> : null}
      <Text style={styles.structuredTitle}>{t('resources.programStructure')}</Text>
      {units.map((unit, unitIndex) => {
        const unitNumber = Number(unit.unit_number || unitIndex + 1);
        const unitTopics = topics.filter((topic) => Number(topic.unit_number) === unitNumber);
        return <Disclosure key={String(unit.id || unitNumber)} title={`${t('resources.unit')} ${unitNumber}: ${String(unit.title || '')}`} summary={t('resources.topicCount', { count: unitTopics.length })} defaultOpen={unitIndex === 0} style={styles.contentSection}>
          {unit.overview ? <Text style={styles.overviewText}>{resourceValue(unit.overview, t)}</Text> : null}
          {['unit_objectives', 'recommended_lesson_purposes', 'recommended_worksheet_types', 'recommended_exam_exercise_types'].map((field) => <ContentValue key={field} name={field} value={unit[field]} />)}
          {unitTopics.map((topic, topicIndex) => <View key={String(topic.id || topicIndex)} style={styles.topicDetail}><Text style={styles.topicDetailTitle}>{t('resources.topicNumber', { number: Number(topic.topic_number || topicIndex + 1) })}: {String(topic.title || '')}</Text>{['subtopic', 'lesson_focus', 'lesson_purpose', 'student_summary', 'learning_objectives', 'success_criteria', 'student_can_do', 'suggested_worksheet_types', 'suggested_exam_exercise_types', 'homework_idea', 'teacher_notes'].map((field) => <ContentValue key={field} name={field} value={topic[field]} />)}</View>)}
        </Disclosure>;
      })}
    </View>;
  }
  const payload = detail;
  return <View style={styles.structuredContent}><Text style={styles.structuredTitle}>{kind === 'video' ? t('resources.videoDetails') : t('resources.resourceContents')}</Text>{Object.entries(payload as Record<string, unknown>).map(([key, value]) => <ContentValue key={key} name={key} value={value} />)}</View>;
}

function ResourceCard({ item, onOpen, chosen, onChoose }: { item: PublicResource; onOpen: () => void; chosen: boolean; onChoose: () => void }) {
  return <View style={[styles.resourceSlot, chosen && styles.resourceSlotChosen]}>
    <ResourceShowcaseCard compact item={item} onPress={onOpen} />
    <Pressable accessibilityRole="checkbox" accessibilityState={{ checked: chosen }} accessibilityLabel={`Select ${item.title}`} onPress={onChoose} style={[styles.selectMark, chosen && styles.selectMarkActive]}><Text style={[styles.selectMarkText, !chosen && styles.selectMarkTextIdle]}>{chosen ? '✓' : ''}</Text></Pressable>
  </View>;
}

